// Disconnected Student entity
var stud = new Student() { StudentId = 1, Name = "Bill" };
stud.Name = "Steve";

using (var context = new SchoolContext())
{
    context.Update<Student>(stud);

    // or: context.Students.Update(stud);
    // or: context.Attach<Student>(stud).State = EntityState.Modified;
    // or: context.Entry<Student>(stud).State = EntityState.Modified;

    context.SaveChanges();
}

var modifiedStudents = new List<Student>()
{
    new Student() { StudentId = 1, Name = "Bill" },
    new Student() { StudentId = 2, Name = "Steve" },
    new Student() { StudentId = 3, Name = "James" }
};

using (var context = new SchoolContext())
{
    context.UpdateRange(modifiedStudents);
    context.SaveChanges();
}
